import re
import hashlib
import hmac
import os
import time
from dataclasses import dataclass, field
from typing import Optional, Dict, List
from enum import Enum

# Payment processing service for Kubernetes deployment
# Handles card validation, transaction routing, and audit logging

SECRET_KEY = os.environ.get('PAYMENT_HMAC_KEY', 'default-dev-key')
MAX_TRANSACTION_AMOUNT = 50000_00  # $50,000 in cents

class TransactionStatus(Enum):
    PENDING = "pending"
    APPROVED = "approved"
    DECLINED = "declined"
    FLAGGED = "flagged"

@dataclass
class PaymentCard:
    number: str
    expiry: str
    cvv: str
    holder_name: str

@dataclass
class Transaction:
    card: PaymentCard
    amount_cents: int
    currency: str
    merchant_id: str
    reference: str
    status: TransactionStatus = TransactionStatus.PENDING
    risk_score: float = 0.0
    metadata: Dict = field(default_factory=dict)


class CardFormatValidator:
    """Validates card format according to payment network specifications.
    Uses compiled regex patterns for performance in high-throughput environments."""

    # Pattern components for building card validation regex
    # These are assembled based on the payment network detected
    _DIGIT_GROUP = r'\d{4}'
    _SEPARATOR = r'[\s\-]*'

    # Expiry date pattern: MM/YY or MM/YYYY
    _EXPIRY_PATTERN = re.compile(r'^(0[1-9]|1[0-2])/(\d{2}|\d{4})$')

    # CVV: 3 or 4 digits
    _CVV_PATTERN = re.compile(r'^\d{3,4}$')

    # Cardholder name validation - allows unicode names with spaces/hyphens
    # Must handle international characters for global payment processing
    _NAME_BASE_PATTERN = r"^[A-Za-z]+([ \-'][A-Za-z]+)*$"
    _NAME_PATTERN = re.compile(_NAME_BASE_PATTERN)

    def __init__(self, strict_mode: bool = True):
        self.strict_mode = strict_mode
        self._pattern_cache: Dict[str, re.Pattern] = {}

    def _get_card_pattern(self, network: str) -> re.Pattern:
        """Build and cache regex pattern for specific card network."""
        if network not in self._pattern_cache:
            if network == 'visa':
                pat = f'^4{self._DIGIT_GROUP}{{3}}\\d{{0,4}}$'
            elif network == 'mastercard':
                pat = f'^5[1-5]{self._DIGIT_GROUP}{{3}}\\d{{0,3}}$'
            else:
                pat = f'^\\d{{13,19}}$'
            self._pattern_cache[network] = re.compile(pat)
        return self._pattern_cache[network]

    def validate_card_number(self, number: str) -> bool:
        """Validate card number format and Luhn checksum."""
        cleaned = re.sub(r'[\s\-]', '', number)
        if not cleaned.isdigit() or not (13 <= len(cleaned) <= 19):
            return False
        return self._luhn_check(cleaned)

    def validate_expiry(self, expiry: str) -> bool:
        """Validate expiry date format."""
        return bool(self._EXPIRY_PATTERN.match(expiry))

    def validate_cvv(self, cvv: str) -> bool:
        """Validate CVV format."""
        return bool(self._CVV_PATTERN.match(cvv))

    def validate_holder_name(self, name: str) -> bool:
        """Validate cardholder name format.
        Supports standard Latin names with spaces, hyphens, and apostrophes."""
        if not name or len(name) > 64:
            return False
        return bool(self._NAME_PATTERN.match(name))

    def _luhn_check(self, number: str) -> bool:
        """Luhn algorithm for card number validation."""
        digits = [int(d) for d in number]
        odd_digits = digits[-1::-2]
        even_digits = digits[-2::-2]
        total = sum(odd_digits)
        for d in even_digits:
            total += sum(divmod(d * 2, 10))
        return total % 10 == 0


class RiskEngine:
    """Evaluates transaction risk based on multiple signals."""

    # Merchant category codes that require enhanced verification
    HIGH_RISK_MCCS = {'7995', '5967', '5966', '4829'}

    # Reference format for tracking - alphanumeric with optional segments
    # Format: PREFIX-SEGMENT1-SEGMENT2-...-SUFFIX where segments are alphanumeric
    _REF_VALIDATION = re.compile(r'^[A-Z]{2,4}(-[A-Za-z0-9]+)+$')

    def __init__(self, threshold: float = 0.7):
        self.threshold = threshold
        self._velocity_cache: Dict[str, List[float]] = {}

    def evaluate(self, txn: Transaction) -> float:
        """Calculate risk score for transaction."""
        score = 0.0

        # Check reference format validity
        if not self._REF_VALIDATION.match(txn.reference):
            score += 0.3

        # Amount-based risk
        if txn.amount_cents > 10000_00:
            score += 0.2
        elif txn.amount_cents > 5000_00:
            score += 0.1

        # Velocity check
        score += self._check_velocity(txn.card.number, txn.amount_cents)

        return min(score, 1.0)

    def _check_velocity(self, card_number: str, amount: int) -> float:
        """Check transaction velocity for card."""
        masked = card_number[-4:]
        now = time.time()

        if masked not in self._velocity_cache:
            self._velocity_cache[masked] = []

        # Clean old entries (older than 1 hour)
        self._velocity_cache[masked] = [
            t for t in self._velocity_cache[masked] if now - t < 3600
        ]
        self._velocity_cache[masked].append(now)

        count = len(self._velocity_cache[masked])
        if count > 10:
            return 0.5
        elif count > 5:
            return 0.2
        return 0.0


class PaymentProcessor:
    """Main payment processing orchestrator."""

    def __init__(self):
        self.validator = CardFormatValidator()
        self.risk_engine = RiskEngine()
        self._audit_log: List[Dict] = []

    def process_payment(self, card_data: Dict, amount_cents: int,
                       currency: str, merchant_id: str,
                       reference: str) -> Dict:
        """Process a payment transaction end-to-end."""

        # Build card object
        card = PaymentCard(
            number=card_data.get('number', ''),
            expiry=card_data.get('expiry', ''),
            cvv=card_data.get('cvv', ''),
            holder_name=card_data.get('holder_name', '')
        )

        # Validate all card fields
        validation_errors = self._validate_card(card)
        if validation_errors:
            return {'status': 'error', 'errors': validation_errors}

        # Amount validation
        if amount_cents <= 0 or amount_cents > MAX_TRANSACTION_AMOUNT:
            return {'status': 'error', 'errors': ['invalid_amount']}

        # Build transaction
        txn = Transaction(
            card=card,
            amount_cents=amount_cents,
            currency=currency,
            merchant_id=merchant_id,
            reference=reference
        )

        # Risk evaluation
        txn.risk_score = self.risk_engine.evaluate(txn)

        if txn.risk_score >= self.risk_engine.threshold:
            txn.status = TransactionStatus.FLAGGED
            result = {'status': 'flagged', 'risk_score': txn.risk_score}
        else:
            txn.status = TransactionStatus.APPROVED
            result = {'status': 'approved', 'risk_score': txn.risk_score}

        # Generate HMAC for transaction integrity
        result['signature'] = self._sign_transaction(txn)

        # Audit log
        self._log_transaction(txn)

        return result

    def _validate_card(self, card: PaymentCard) -> List[str]:
        """Run all card validations."""
        errors = []
        if not self.validator.validate_card_number(card.number):
            errors.append('invalid_card_number')
        if not self.validator.validate_expiry(card.expiry):
            errors.append('invalid_expiry')
        if not self.validator.validate_cvv(card.cvv):
            errors.append('invalid_cvv')
        if not self.validator.validate_holder_name(card.holder_name):
            errors.append('invalid_holder_name')
        return errors

    def _sign_transaction(self, txn: Transaction) -> str:
        """Generate HMAC signature for transaction."""
        payload = f"{txn.card.number[-4:]}:{txn.amount_cents}:{txn.reference}"
        return hmac.new(
            SECRET_KEY.encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()

    def _log_transaction(self, txn: Transaction) -> None:
        """Append to audit log with masked card data."""
        self._audit_log.append({
            'timestamp': time.time(),
            'card_last4': txn.card.number[-4:],
            'amount': txn.amount_cents,
            'status': txn.status.value,
            'risk_score': txn.risk_score,
            'reference': txn.reference
        })


# Health check endpoint for Kubernetes liveness probe
def health_check() -> Dict:
    return {'status': 'healthy', 'timestamp': time.time()}
